package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.Produto.StatusProduto;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="produto") public class ProdutoEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(name="categoria_id") public UUID categoriaId; @Column(name="codigo_barras",nullable=false,length=100) public String codigoBarras; @Column(length=80) public String sku; @Column(nullable=false,length=200) public String nome; @Column(columnDefinition="text") public String descricao; @Column(name="imagem_url",columnDefinition="text") public String imagemUrl; @Column(name="unidade_medida",nullable=false,length=10) public String unidadeMedida; @Column(name="preco_compra",nullable=false,precision=14,scale=2) public BigDecimal precoCompra; @Column(name="preco_venda",nullable=false,precision=14,scale=2) public BigDecimal precoVenda; @Column(name="estoque_atual",nullable=false,precision=14,scale=3) public BigDecimal estoqueAtual; @Column(name="estoque_minimo",nullable=false,precision=14,scale=3) public BigDecimal estoqueMinimo; @Column(name="permite_estoque_negativo",nullable=false) public boolean permiteEstoqueNegativo; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) public StatusProduto status; @Column(name="created_at",nullable=false) public Instant criadoEm; @Column(name="updated_at",nullable=false) public Instant atualizadoEm; public ProdutoEntity() {} }
